INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','noun-modifiers','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"noun-modifiers","title":"Noun modifiers, compound phrases and nominalisation","level":"C1","order":66,"summary":"Build compact noun phrases and understand how turning actions into nouns changes a sentence’s focus.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Nouns can modify other nouns","Measure compounds before nouns","Possessive relationships and of phrases","Nominalisation and clarity"],"rules":[{"title":"Nouns can modify other nouns","explanation":"A noun before another noun often classifies its purpose or type. The final noun is usually the head and controls number and agreement. The first noun often stays singular: a book shelf, two book shelves. Some established compounds keep a plural modifier.","pattern":"a **shoe shop** / two **shoe shops**","commonMistakes":["A sports centre is an established plural modifier. The singular-modifier pattern has lexical exceptions."],"examples":["Choose the modifier: “It is a **2-hour** task to prepare the visitor guide.”","Choose the modifier: “It is a **3-hour** task to restore the old portrait.”"],"skill":"form"},{"title":"Measure compounds before nouns","explanation":"A measurement used as a compound modifier usually has a singular unit and is often hyphenated. When the same measurement follows the noun as a separate phrase, the unit can be plural.","pattern":"a **three-hour** journey / a journey of **three hours**","commonMistakes":["A three-hours journey incorrectly pluralises the unit inside the usual compound modifier."],"examples":["“The task of preparing the visitor guide took 2 **hours**.”","“The task of restoring the old portrait took 3 **hours**.”"],"skill":"meaning"},{"title":"Possessive relationships and of phrases","explanation":"A possessive can express relationships beyond ownership, including time and association. Noun modifiers often classify; possessives often identify a particular relationship. An of phrase may be clearer with long or abstract noun phrases.","pattern":"a **day’s** work / the roof **of the building**","commonMistakes":["A children’s book and a child’s book can differ: the former can name a category, the latter a book belonging to one child."],"examples":["Choose the possessive duration: “We completed a **day’s** work on the visitor guide.”","Choose the possessive duration: “We completed a **day’s** work on the old portrait.”"],"skill":"contrast"},{"title":"Nominalisation and clarity","explanation":"Nominalisation turns an action or quality into a noun, often useful in academic writing: decide → decision, develop → development. It can make a process the subject of a sentence but can also hide who acted. Keep the agent explicit when responsibility matters.","pattern":"We decided quickly. → **Our decision** was quick.","commonMistakes":["Long strings of abstract nouns are not automatically clearer or more precise than verbs."],"examples":["“A decision was made to prepare the visitor guide.” Which revision names the decision-maker clearly? → **The committee decided to prepare the visitor guide.**","“A decision was made to restore the old portrait.” Which revision names the decision-maker clearly? → **The committee decided to restore the old portrait.**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-noun-modifiers"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"2a69e30f-dc38-5831-a736-27a0573668ea","topicSlug":"noun-modifiers","level":"C1","prompt":"Choose the modifier: “It is a ____ task to prepare the visitor guide.”","choices":[{"id":"A","text":"2-hour"},{"id":"B","text":"2-hours"},{"id":"C","text":"2 hours''"},{"id":"D","text":"2-hourly"}],"answerId":"A","hint":"Before a noun, build **number + singular unit** as a compound modifier.","explanation":"A compound measurement before task uses a singular unit: **2-hour**.","keywords":["measure-compound"],"skill":"measure-compound","contextKey":"noun-modifiers-1","fingerprint":"b1a5ba1c370e742ba20e8606b3d17dccbc176a4af1619807823e1e84735d504e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-noun-modifiers"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Before a noun, build **number + singular unit** as a compound modifier.","A compound measurement before task uses a singular unit: **2-hour**.","Choose **2-hour**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A compound measurement before task uses a singular unit: **2-hour**.","B":"The unit stays singular inside this compound modifier.","C":"This is a possessive-shaped duration, not the adjective compound after a.","D":"Hourly means occurring each hour, not lasting this many hours."}}},{"id":"8e157cfe-7d99-52bd-ada5-f74262972175","topicSlug":"noun-modifiers","level":"C1","prompt":"“The task of preparing the visitor guide took 2 ____.”","choices":[{"id":"A","text":"hour’s"},{"id":"B","text":"hours"},{"id":"C","text":"hour"},{"id":"D","text":"hourly"}],"answerId":"B","hint":"This measurement stands **after the verb**, outside a compound modifier.","explanation":"After the verb took, the measurement is a normal plural noun phrase: **hours**.","keywords":["measure-after-noun"],"skill":"measure-after-noun","contextKey":"noun-modifiers-1","fingerprint":"bf4a04a3c79727051fe4de33ccf66d92b9698ea7326530d0ec6bf48d7d8bcab1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-noun-modifiers"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["This measurement stands **after the verb**, outside a compound modifier.","After the verb took, the measurement is a normal plural noun phrase: **hours**.","Choose **hours**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A possessive apostrophe is not needed to state this duration.","B":"After the verb took, the measurement is a normal plural noun phrase: **hours**.","C":"The number is greater than one, so the separate measure noun is plural.","D":"Hourly is an adjective/adverb, not the unit noun required here."}}},{"id":"7a092b44-7fd8-551c-a854-15ad78113f46","topicSlug":"noun-modifiers","level":"C1","prompt":"Choose the possessive duration: “We completed a ____ work on the visitor guide.”","choices":[{"id":"A","text":"day’s"},{"id":"B","text":"days’"},{"id":"C","text":"days"},{"id":"D","text":"day"}],"answerId":"A","hint":"The article **a** specifies one day, and the phrase asks for its possessive form.","explanation":"A singular time unit in the possessive takes **’s**: a day’s work.","keywords":["one-day-possession"],"skill":"one-day-possession","contextKey":"noun-modifiers-1","fingerprint":"84e0461b3013c848278d8488f7a2fab841c26e890e8317ec75949d3a6ffd2007","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-noun-modifiers"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The article **a** specifies one day, and the phrase asks for its possessive form.","A singular time unit in the possessive takes **’s**: a day’s work.","Choose **day’s**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A singular time unit in the possessive takes **’s**: a day’s work.","B":"Days’ is plural possession, but a specifies one day.","C":"A plain plural lacks the possessive marking and conflicts with a.","D":"The requested duration phrase is possessive: a day’s work."}}},{"id":"afd767fe-3432-5518-aaa3-16d3cf91fad8","topicSlug":"noun-modifiers","level":"C1","prompt":"“A decision was made to prepare the visitor guide.” Which revision names the decision-maker clearly?","choices":[{"id":"A","text":"A decision about the visitor guide was made."},{"id":"B","text":"The making of a decision to prepare the visitor guide occurred."},{"id":"C","text":"It was decided to prepare the visitor guide."},{"id":"D","text":"The committee decided to prepare the visitor guide."}],"answerId":"D","hint":"Look for an explicit **actor as subject**, not just a noun naming the decision.","explanation":"The active verb and explicit subject **the committee** identify who made the decision.","keywords":["nominalisation-agent"],"skill":"nominalisation-agent","contextKey":"noun-modifiers-1","fingerprint":"53e877bedee8980109aa9de6ecece62a5af405ce5b098305576d33a44446736e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-noun-modifiers"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Look for an explicit **actor as subject**, not just a noun naming the decision.","The active verb and explicit subject **the committee** identify who made the decision.","Choose **The committee decided to prepare the visitor guide.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This still omits who made the decision.","B":"The nominalised wording still hides the decision-maker.","C":"This impersonal passive also omits the decision-maker.","D":"The active verb and explicit subject **the committee** identify who made the decision."}}},{"id":"22b74615-f002-5acf-af59-0d16fa2c6eca","topicSlug":"noun-modifiers","level":"C1","prompt":"Choose the modifier: “It is a ____ task to restore the old portrait.”","choices":[{"id":"A","text":"3-hourly"},{"id":"B","text":"3-hour"},{"id":"C","text":"3-hours"},{"id":"D","text":"3 hours''"}],"answerId":"B","hint":"Before a noun, build **number + singular unit** as a compound modifier.","explanation":"A compound measurement before task uses a singular unit: **3-hour**.","keywords":["measure-compound"],"skill":"measure-compound","contextKey":"noun-modifiers-2","fingerprint":"6c0d292d169e08339fec028dfd0309c542928f3bf77787ca5c04faadd19bffe3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-noun-modifiers"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Before a noun, build **number + singular unit** as a compound modifier.","A compound measurement before task uses a singular unit: **3-hour**.","Choose **3-hour**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Hourly means occurring each hour, not lasting this many hours.","B":"A compound measurement before task uses a singular unit: **3-hour**.","C":"The unit stays singular inside this compound modifier.","D":"This is a possessive-shaped duration, not the adjective compound after a."}}},{"id":"c5e90fbc-7bbc-514e-a473-99e03f523051","topicSlug":"noun-modifiers","level":"C1","prompt":"“The task of restoring the old portrait took 3 ____.”","choices":[{"id":"A","text":"hours"},{"id":"B","text":"hour"},{"id":"C","text":"hourly"},{"id":"D","text":"hour’s"}],"answerId":"A","hint":"This measurement stands **after the verb**, outside a compound modifier.","explanation":"After the verb took, the measurement is a normal plural noun phrase: **hours**.","keywords":["measure-after-noun"],"skill":"measure-after-noun","contextKey":"noun-modifiers-2","fingerprint":"eb3305bcb028980e12d158f0553a9cf6864123385e0743f357ada268df0ee045","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-noun-modifiers"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["This measurement stands **after the verb**, outside a compound modifier.","After the verb took, the measurement is a normal plural noun phrase: **hours**.","Choose **hours**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After the verb took, the measurement is a normal plural noun phrase: **hours**.","B":"The number is greater than one, so the separate measure noun is plural.","C":"Hourly is an adjective/adverb, not the unit noun required here.","D":"A possessive apostrophe is not needed to state this duration."}}},{"id":"d4816997-0e81-5a7f-ac22-96d64ab6ce0b","topicSlug":"noun-modifiers","level":"C1","prompt":"Choose the possessive duration: “We completed a ____ work on the old portrait.”","choices":[{"id":"A","text":"days"},{"id":"B","text":"day"},{"id":"C","text":"day’s"},{"id":"D","text":"days’"}],"answerId":"C","hint":"The article **a** specifies one day, and the phrase asks for its possessive form.","explanation":"A singular time unit in the possessive takes **’s**: a day’s work.","keywords":["one-day-possession"],"skill":"one-day-possession","contextKey":"noun-modifiers-2","fingerprint":"ec1b67bd594f3061add8c7c203f2445f7dc4eb49c743569df386d54fe4870914","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-noun-modifiers"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The article **a** specifies one day, and the phrase asks for its possessive form.","A singular time unit in the possessive takes **’s**: a day’s work.","Choose **day’s**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A plain plural lacks the possessive marking and conflicts with a.","B":"The requested duration phrase is possessive: a day’s work.","C":"A singular time unit in the possessive takes **’s**: a day’s work.","D":"Days’ is plural possession, but a specifies one day."}}},{"id":"5c35d870-33c